import static org.junit.Assert.*;

import org.jsoup.nodes.*;
import org.jsoup.parser.*;
import org.junit.Test;

import java.io.Reader;
import java.io.StringReader;
import java.util.List;

public class XmlTreeBuilderTest {

    @Test(expected = IllegalArgumentException.class)
    public void processUnexpectedTokenTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token token = new Token(Tag.valueOf("Test"), String.valueOf("Test"));
        xmlTreeBuilder.process(token);
    }

    @Test
    public void insertNodeTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Node node = new Element(Tag.valueOf("Test"));
        xmlTreeBuilder.insertNode(node);
        assertTrue(xmlTreeBuilder.getStack().get(0).childNodes().contains(node));
    }

    @Test(expected = IllegalArgumentException.class)
    public void insertNodeWithUnmatchedNodeAndTokenTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Node node = new Element(Tag.valueOf("Test"));
        Token token = new Token(Tag.valueOf("Test1"),  String.valueOf("Test1"));
        xmlTreeBuilder.insertNode(node, token);
    }

    @Test
    public void newInstanceTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        assertTrue(xmlTreeBuilder.newInstance() instanceof XmlTreeBuilder);
    }

    @Test
    public void parseTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Reader reader = new StringReader("<root></root>");
        assertEquals(Document.OutputSettings.Syntax.xml, xmlTreeBuilder.parse(reader, "www.example.com").outputSettings().syntax());
    }

    @Test
    public void parseFragmentTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        String inputFragment = "<testFragment></testFragment>";
        List<Node> nodes = xmlTreeBuilder.parseFragment(inputFragment, "www.example.com", Parser.xmlParser());
        assertTrue(nodes.get(0) instanceof Element);
        assertEquals("testFragment", ((Element) nodes.get(0)).tag().toString());
    }

    @Test
    public void popStackToCloseWhenElementNotFoundTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.EndTag endTag = new Token.EndTag("test-tag");
        int stackSizeBeforePop = xmlTreeBuilder.getStack().size();
        xmlTreeBuilder.popStackToClose(endTag);
        assertEquals(stackSizeBeforePop, xmlTreeBuilder.getStack().size());
    }

    @Test
    public void popStackToCloseWhenElementFoundTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        xmlTreeBuilder.insert(new Token.StartTag("test-tag"));
        Token.EndTag endTag = new Token.EndTag("test-tag");
        int stackSizeBeforePop = xmlTreeBuilder.getStack().size();
        xmlTreeBuilder.popStackToClose(endTag);
        assertEquals(stackSizeBeforePop - 1, xmlTreeBuilder.getStack().size());
    }
}
